using MediatR;using OAS.Application.Abstractions.Persistence;using OAS.Application.Abstractions.Persistence.Specifications;using OAS.Contracts.Accounting.Currencies;using OAS.Contracts.Common.Pagination;using OAS.Domain.Accounting.Entities;
namespace OAS.Application.Accounting.Currencies.Queries.GetCurrencies;public sealed class GetCurrenciesQueryHandler(IReadRepository<Currency,Guid> repository):IRequestHandler<GetCurrenciesQuery,PagedResult<CurrencyDto>>{public async Task<PagedResult<CurrencyDto>> Handle(GetCurrenciesQuery r,CancellationToken ct){var p=r.Request.Normalize();var s=new Specification<Currency>();if(!string.IsNullOrWhiteSpace(p.Search)){var q=p.Search;s.Where(x=>x.Code.Contains(q)||x.NameAr.Contains(q)||(x.NameEn!=null&&x.NameEn.Contains(q)));}s.AddSort(string.Equals(p.SortBy,"namear",StringComparison.OrdinalIgnoreCase)?nameof(Currency.NameAr):nameof(Currency.Code),p.SortDirection).ApplyPaging((p.PageNumber-1)*p.PageSize,p.PageSize);var page=await repository.GetPageAsync(s,ct);return new(){Items=page.Items.Select(e=>new CurrencyDto(e.Id,e.Code,e.NameAr,e.NameEn,e.Symbol,e.DecimalPlaces,e.IsActive,Convert.ToBase64String(e.RowVersion))).ToArray(),PageNumber=p.PageNumber,PageSize=p.PageSize,TotalCount=page.TotalCount};}}
